#include <cuda_runtime.h>
#include <vector>
#include <fstream>
#include <chrono>
#include <cstdio>
#include <string>
#include "source_kernels.cuh"
#include "corrected_compute.cuh"
#include "study_contract.h"
#define C(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA:%s:%d\n",cudaGetErrorString(e),__LINE__);exit(7);}}while(0)
template<class T>std::vector<T>rd(std::string p,int n){std::ifstream f(p,std::ios::binary);std::vector<T>a(n);f.read((char*)a.data(),n*sizeof(T));if(!f||f.peek()!=EOF)exit(2);return a;}
template<class T>struct B{T *base,*p;std::vector<T>initial;B(std::vector<T>a,T guard){initial.assign(16,guard);initial.insert(initial.end(),a.begin(),a.end());initial.insert(initial.end(),16,guard);C(cudaMalloc(&base,initial.size()*sizeof(T)));p=base+16;reset();}void reset(){C(cudaMemcpy(base,initial.data(),initial.size()*sizeof(T),cudaMemcpyHostToDevice));}void append(std::vector<int>&out){std::vector<T>a(initial.size());C(cudaMemcpy(a.data(),base,a.size()*sizeof(T),cudaMemcpyDeviceToHost));for(T x:a)out.push_back(x);}};
struct Work{int k,w,h,kw,kh,n;B<unsigned char>image,kernel;B<int>sad,minimum,count;Work(int id):k(id),w(WS[k]),h(HS[k]),kw(KWS[k]),kh(KHS[k]),n(NS[k]),image(rd<unsigned char>("image"+std::to_string(k)+".bin",3*w*h),231),kernel(rd<unsigned char>("kernel"+std::to_string(k)+".bin",3*kw*kh),231),sad(std::vector<int>(n,-777),-99999),minimum(std::vector<int>(1,20),-99999),count(std::vector<int>(1,0),-99999){}void reset(){image.reset();kernel.reset();sad.reset();minimum.reset();count.reset();}void prefix(std::vector<int>&out){out.insert(out.end(),{w,h,kw,kh,n,kw*kh,3});image.append(out);kernel.append(out);sad.append(out);minimum.append(out);count.append(out);}double run(){double seconds=0;for(int r=0;r<3;r++){int m=20;C(cudaMemcpy(minimum.p,&m,4,cudaMemcpyHostToDevice));C(cudaMemset(count.p,0,4));C(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();compute_sad_array_corrected<<<dim3((w+15)/16,(h+15)/16),dim3(16,16)>>>(sad.p,image.p,kernel.p,n,w,h,kw,kh,kw*kh);find_min_in_sad_array<<<(n+255)/256,256>>>(n,sad.p,minimum.p);get_num_of_occurrences<<<(n+255)/256,256>>>(n,sad.p,minimum.p,count.p);C(cudaGetLastError());C(cudaDeviceSynchronize());seconds+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();}return seconds/3;}void tail(std::vector<int>&out){sad.append(out);minimum.append(out);count.append(out);image.append(out);kernel.append(out);}};
int main(){auto expected=rd<int>("oracle_full_i32.bin",COUNT);std::vector<Work*>work;for(int k=0;k<5;k++)work.push_back(new Work(k));for(auto w:work)w->run();for(int trial=1;trial<=5;trial++){std::vector<int>out;for(auto w:work){w->reset();w->prefix(out);}if(out.size()!=PREFIX)return 3;double seconds=0;for(auto w:work)seconds+=w->run();for(auto w:work)w->tail(out);bool good=out.size()==COUNT;long long maxerr=0;int mismatch=0;for(int i=0;i<COUNT;i++){long long e=llabs((long long)out[i]-expected[i]);mismatch+=e!=0;maxerr=std::max(maxerr,e);}good=good&&mismatch==0;std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/sad_trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)out.data(),out.size()*4);f.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%lld,\"max_rel_error\":null,\"jit_excluded\":true,\"timing_region\":\"fivecase_source3GPUstages_R3regionmean_sum_contextsync\",\"iterations\":3,\"internal_repeats\":3,\"kernel_launches\":45,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,good?"true":"false",out.size(),maxerr,path.c_str(),out.size());fflush(stdout);if(!good)return 4;}return 0;}
